Task: Put the red cube into the red tray and the blue cube into the blue tray.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """Sort cubes by colour into matching trays."""
  5|     robot.home()
  6| 
  7|     # Get current scene description
  8|     obs = robot.observe()
  9| 
 10|     # Separate cubes and trays
 11|     cubes = {name: obj for name, obj in obs['objects'].items() if obj['shape'] == 'cube'}
 12|     trays = {name: fix for name, fix in obs['fixtures'].items() if fix['kind'] == 'tray'}
 13| 
 14|     # Map colour -> tray name (e.g., 'red' -> 'red_tray')
 15|     colour_to_tray = {}
 16|     for name, fix in trays.items():
 17|         colour_to_tray[fix['color']] = name
 18| 
 19|     overall_success = True
 20| 
 21|     for cube_name, cube in cubes.items():
 22|         colour = cube['color']
 23|         tray_name = colour_to_tray.get(colour)
 24|         if tray_name is None:
 25|             robot.log(f"No tray found for colour '{colour}'")
 26|             overall_success = False
 27|             continue
 28| 
 29|         # Get up-to-date poses (perception is noisy)
 30|         cube_pose = robot.get_pose(cube_name)
 31|         tray_pose = robot.get_pose(tray_name)
 32| 
 33|         if not _pick_and_place(robot, cube_pose, tray_pose):
 34|             robot.log(f"Failed to place {cube_name} into {tray_name}")
 35|             overall_success = False
 36| 
 37|     return overall_success
 38| 
 39| 
 40| def _pick_and_place(robot, cube_pose, tray_pose):
 41|     """Attempt one pick‑and‑place cycle. Returns True on success."""
 42|     max_attempts = 2
 43|     lift_height = 0.10          # safe travel height above the table
 44|     grasp_offset = 0.02         # how far above the cube centre we close the fingers
 45|     place_offset = 0.02         # how far above the tray bottom we release
 46|     tolerance = 0.04            # acceptable xy error for placement (metres)
 47| 
 48|     for attempt in range(max_attempts):
 49|         try:
 50|             # 1. Move above the cube
 51|             above_cube = [cube_pose['pos'][0], cube_pose['pos'][1], lift_height]
 52|             robot.move_to(*above_cube, speed=0.2)
 53| 
 54|             # 2. Descend to a grasp height (just above the cube centre)
 55|             grasp_z = cube_pose['pos'][2] + grasp_offset
 56|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], grasp_z,
 57|                           speed=0.05, yaw=cube_pose['yaw'])
 58| 
 59|             # 3. Close fingers
 60|             if not robot.grasp():
 61|                 robot.release()  # ensure hand is open before retrying
 62|                 continue
 63| 
 64|             # 4. Verify we actually hold something
 65|             if robot.holding() is None:
 66|                 robot.release()
 67|                 continue
 68| 
 69|             # 5. Lift the cube to safe height
 70|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], lift_height,
 71|                           speed=0.05)
 72| 
 73|             # 6. Move above the target tray
 74|             above_tray = [tray_pose['pos'][0], tray_pose['pos'][1], lift_height]
 75|             robot.move_to(*above_tray, speed=0.2)
 76| 
 77|             # 7. Lower to just above the tray bottom
 78|             place_z = tray_pose['pos'][2] + place_offset
 79|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], place_z,
 80|                           speed=0.05, yaw=tray_pose['yaw'])
 81| 
 82|             # 8. Release the cube
 83|             robot.release()
 84|             robot.wait(0.05)  # brief pause to let the object settle
 85| 
 86|             # 9. Retract to safe height
 87|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], lift_height,
 88|                           speed=0.05)
 89| 
 90|             # 10. Verification: cube should be released and near tray centre
 91|             cube_after = robot.get_pose(cube_name)
 92|             tray_after = robot.get_pose(tray_name)  # tray pose is static but refresh anyway
 93|             dx = cube_after['pos'][0] - tray_after['pos'][0]
 94|             dy = cube_after['pos'][1] - tray_after['pos'][1]
 95|             if math.hypot(dx, dy) > tolerance:
 96|                 robot.log(f"Verification failed: cube {cube_name} off target by {math.hypot(dx, dy):.3f} m")
 97|                 # Ensure hand is open before retrying
 98|                 robot.release()
 99|                 continue
100| 
101|             return True  # success for this cube
102| 
103|         except Exception as e:  # catches MotionError and other unexpected issues
104|             robot.log(f"Attempt {attempt+1} failed: {e}")
105|             robot.release()  # try to leave the hand open
106|             continue
107| 
108|     # If we exit the loop, all attempts failed
109|     return False

